/**
 * Insights copy dictionary: FARSI (نمایش فارسی روان، نه ترجمهٔ واژه‌به‌واژه).
 *
 * Same discipline as the main dictionary pair: this module must satisfy
 * `InsightsCopy` (the typeof of insights-copy-en.ts) exactly: adding a key
 * to English without translating it here fails typecheck. It lives in the
 * lazy /insights route chunk with its English twin.
 *
 * Wording decisions (02-page-design-spec.md §7 + I15 specs):
 *   Warning → هشدار · Normal → عادی · Context → اطلاعات زمینه‌ای
 *   Stale → قدیمی · Limited history → تاریخچهٔ کوتاه · No data → بدون داده
 *   Relaxed → پایدار · Cautious → احتیاط · Stressed → پرتنش · Alarmed → بحرانی
 * «بحرانی» عمداً با «هشدار» (چیپ کارت) هم‌معنی نیست تا برچسب کلی و چیپ
 * کارت با هم اشتباه نشوند.
 *
 * I15 (UI spec): فارسی زبان اول است؛ نام شاخص‌ها ابتدا ساده و مردمی است
 * (F6) و برچسب فنی به‌صورت تیکر کوچک لاتین کنارش می‌نشیند (G8). جمله‌های
 * پیامد بر اساس وضعیت انتخاب می‌شوند (F4): «معمولاً»، «تمایل دارد»، بدون
 * واژهٔ خرید/فروش، حداکثر حدود ۱۵ واژه، و از جایگاه گفته‌شده مثل «اگر وام
 * مسکن دارید…».
 *
 * اعداد درون متن با ارقام فارسی نوشته شده‌اند؛ اعداد پویا فقط موقع رندر
 * با Intl فارسی می‌شوند (قاعدهٔ AGENTS.md). همهٔ متن‌ها «اطلاعات عمومی»
 * اند، نه توصیه. اطلاع رسمی FRED باید عیناً به انگلیسی بماند (Block N1).
 */
