    aboutCreditsLine:
      'منابع داده عبارت‌اند از: فدرال رزرو آمریکا (FRED)، بانک مرکزی اروپا، بانک مرکزی استرالیا، اداره آمار استرالیا (با مجوز CC BY 4.0)، بانک جهانی، Frankfurter، gold-api.com و برای بازارهای سهام جهان EODHD و Yahoo Finance.',
    aboutGeneralInfo: 'فقط اطلاعات عمومی ارائه می‌شود و این مطالب توصیه مالی نیستند.',
    aboutSourcesTitle: 'منابع',
    // گام ۱ (بند G3) + گام ۲: فهرست دقیق — VIX دادهٔ Cboe از طریق FRED
    // است (© Cboe) و سنگ‌آهن فقط زمینه است و هرگز در حکم‌ها حساب نمی‌شود.
    // درخواست مالک (منبع‌ها بیرون از کارت‌ها): نام و پیوند هر منبع فقط
    // همین‌جا و در پنل جزئیات آمده است، نه روی کارت‌ها.
    aboutSourcesBody:
      'منابع داده شامل نهادهای رسمی و تأمین‌کنندگان داده‌های بازار هستند: فدرال رزرو آمریکا (FRED)، اداره آمار کار آمریکا از طریق FRED، بانک مرکزی اروپا، بانک مرکزی استرالیا، اداره آمار استرالیا (با مجوز CC BY 4.0) و بانک جهانی. داده‌های بازار نیز از Frankfurter (نرخ‌های مرجع بانک مرکزی اروپا)، gold-api.com، EODHD و Yahoo Finance دریافت می‌شوند. داده‌های بازارهای سهام جهان، قیمت‌های بازار کالاها و نرخ‌های ارز نیز از این منابع تأمین می‌شوند. شاخص ترس بازار (VIX) بر پایه داده‌های Cboe است که از طریق FRED بازنشر می‌شود (© Cboe). قیمت سنگ‌آهن فقط برای تکمیل تصویر بازار نمایش داده می‌شود و در تعیین وضعیت هیچ‌یک از حوزه‌ها دخالت ندارد. نام و پیوند منابع در پنل جزئیات و همین بخش «منابع» آمده است، نه روی کارت‌های شاخص. مجوزهای سطح رایگان برای استفاده شخصی هستند و پیش از هرگونه استفاده تجاری باید شرایط مجوز دوباره بررسی شود.',
    // اطلاع رسمی FRED باید عین متن انگلیسی بماند (Block N1) و روی خطِ
    // مستقلِ dir=ltr بنشیند (روند ۲۴: متن فارسی درون خط لاتین به‌هم می‌ریخت).
    fredNotice:
      'This product uses the FRED® API but is not endorsed or certified by the Federal Reserve Bank of St. Louis.',
    fredLocalNote:
      'اطلاعیه رسمی FRED: این محصول از رابط برنامه‌نویسی FRED استفاده می‌کند، اما از سوی بانک فدرال رزرو سنت‌لوئیس تأیید یا گواهی نشده است.',
    fredTerms: 'شرایط استفاده از FRED',
    attributionTitle: 'منابع و ذکر منبع',
    attributionRba: 'منبع داده: بانک مرکزی استرالیا (RBA)، ۲۰۲۶.',
    attributionAbs: 'منبع: اداره آمار استرالیا (ABS)، با مجوز CC BY 4.0.',
    attributionEcb: 'نرخ‌های مرجع بانک مرکزی اروپا از طریق Frankfurter ارائه می‌شوند. منبع اصلی: بانک مرکزی اروپا.',
    attributionBasket: 'شاخص دلاری کورنا بر اساس نرخ‌های مرجع بانک مرکزی اروپا محاسبه می‌شود و شاخص رسمی DXY نیست.',
    // روند ۴۴ (مالک): خط منبع بخش بازارهای سهام جهان، از خود بخش به
    // پابرگ صفحه (کنار سایر ذکر منبع‌ها) منتقل شد.
    attributionEodhd:
      'منبع: EODHD با پشتیبانی Yahoo Finance. ارقام بازارها، قیمت پایانی روز و بر اساس ارز محلی هر بازار هستند.',
    aboutScheduleTitle: 'زمان‌بندی به‌روزرسانی داده‌ها',
    aboutScheduleBody:
      'یک فرایند زمان‌بندی‌شده هر روز ساعت ۰۴:۲۰ به وقت هماهنگ جهانی (UTC) همه منابع را به‌روزرسانی می‌کند و نسخه‌ای از پیش محاسبه‌شده از داده‌ها را ذخیره می‌کند. صفحه‌ای که مشاهده می‌کنید همین نسخه ذخیره‌شده را نمایش می‌دهد. داده‌های روزانه هر روز و داده‌های ماهانه و فصلی هم‌زمان با انتشار رسمی ناشر مربوطه به‌روز می‌شوند. داده‌های بازارهای سهام جهان طبق برنامه‌ای جداگانه، در شامگاه روزهای کاری و ساعت ۲۳:۳۰ به وقت UTC به‌روزرسانی می‌شوند.',
